def verify_isbn(isbn: str) -> str:
    # Split the ISBN into its constituent parts
    parts = isbn.split("-")

    # Calculate the sum of the digits in the ISBN
    sum = 0
    for i in range(len(parts) - 1):
        sum += int(parts[i])

    # Calculate the checksum
    checksum = (sum % 11)
    if checksum == 10:
        checksum = "X"
    else:
        checksum = str(checksum)

    # Check if the checksum is correct
    if checksum == parts[-1]:
        return "Right"
    else:
        # Return the corrected ISBN
        return "-".join(parts[:-1]) + "-" + checksum
    return "Right"

